insert into permissions (code, description) values
  ('DASHBOARD_VIEW', 'View the dashboard statistics'),
  ('CONTENT_WRITE', 'Create and edit news, publications, events, resources (drafts and submit for review)'),
  ('CONTENT_PUBLISH', 'Publish, schedule, unpublish and archive content'),
  ('CONTENT_DELETE', 'Delete content'),
  ('MEDIA_UPLOAD', 'Upload and edit media files'),
  ('MEDIA_DELETE', 'Delete media files'),
  ('CATEGORY_MANAGE', 'Manage categories'),
  ('HOMEPAGE_MANAGE', 'Edit homepage sections'),
  ('PARTNER_MANAGE', 'Manage partners'),
  ('MESSAGES_VIEW', 'Read and handle contact messages'),
  ('AUDIT_VIEW', 'View the audit log'),
  ('USER_MANAGE', 'Manage administrator accounts'),
  ('ROLE_MANAGE', 'Configure which permissions each role has'),
  ('SETTINGS_MANAGE', 'Change website settings');
insert into roles (name, description, system_role) values
  ('SUPER_ADMIN', 'Full system access', true),
  ('ADMIN', 'Manages approved website content', true),
  ('EDITOR', 'Creates and edits content, submits it for approval', true);
insert into role_permissions (role_id, permission_code) select r.id, p.code from roles r, permissions p where r.name = 'SUPER_ADMIN' and p.code in ('DASHBOARD_VIEW', 'CONTENT_WRITE', 'CONTENT_PUBLISH', 'CONTENT_DELETE', 'MEDIA_UPLOAD', 'MEDIA_DELETE', 'CATEGORY_MANAGE', 'HOMEPAGE_MANAGE', 'PARTNER_MANAGE', 'MESSAGES_VIEW', 'AUDIT_VIEW', 'USER_MANAGE', 'ROLE_MANAGE', 'SETTINGS_MANAGE');
insert into role_permissions (role_id, permission_code) select r.id, p.code from roles r, permissions p where r.name = 'ADMIN' and p.code in ('DASHBOARD_VIEW', 'CONTENT_WRITE', 'CONTENT_PUBLISH', 'CONTENT_DELETE', 'MEDIA_UPLOAD', 'MEDIA_DELETE', 'CATEGORY_MANAGE', 'HOMEPAGE_MANAGE', 'PARTNER_MANAGE', 'MESSAGES_VIEW');
insert into role_permissions (role_id, permission_code) select r.id, p.code from roles r, permissions p where r.name = 'EDITOR' and p.code in ('DASHBOARD_VIEW', 'CONTENT_WRITE', 'MEDIA_UPLOAD');
